/**
 * What was done through one delegation, newest first, narrowed by a search (words of the component, the action or the event)
 * and by a menu of the date whose two days never go the wrong way round, as every list of the design system.
 *
 * @module     local_delegateaccount/activity
 * @copyright  2026 Didactika.org
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

import {getString, get_strings as getStrings} from 'core/str';
import List from 'local_delegateaccount/local/list';
import {debounce} from 'local_delegateaccount/local/ui';
import {init as fitTables} from 'local_delegateaccount/fit_tables';

/** Filters of the report, as they are named in the address and in the web service. */
const FILTERS = ['datefrom', 'dateto', 'search'];

/**
 * A day as a date field writes it.
 *
 * @param {Date} date The day.
 * @returns {string} The day, as year-month-day.
 */
const iso = (date) => [date.getFullYear(), String(date.getMonth() + 1).padStart(2, '0'), String(date.getDate()).padStart(2, '0')]
    .join('-');

/**
 * The usual periods, counted from today and kept inside the bounds of the delegation.
 *
 * @param {string} min The first day that can be chosen, or empty.
 * @param {string} max The last day that can be chosen, or empty.
 * @returns {Object<string, string[]>} The first and the last day of each period.
 */
const periods = (min, max) => {
    const today = new Date();
    const back = (days) => new Date(today.getFullYear(), today.getMonth(), today.getDate() - days);
    const clamp = (day) => {
        if (min && day < min) {
            return min;
        }
        return max && day > max ? max : day;
    };
    const list = {
        today: [iso(today), iso(today)],
        week: [iso(back(6)), iso(today)],
        month: [iso(new Date(today.getFullYear(), today.getMonth(), 1)), iso(today)],
        last30: [iso(back(29)), iso(today)],
    };
    return Object.fromEntries(Object.entries(list).map(([key, [from, to]]) => [key, [clamp(from), clamp(to)]]));
};

/**
 * Two days that bound a period, never the wrong way round: when the day just chosen passes the other one, the other one moves to
 * it.
 *
 * @param {string} from The first day, or empty.
 * @param {string} to The last day, or empty.
 * @param {string} changed Which of the two was just chosen: from or to.
 * @returns {string[]} The two days, in order.
 */
const orderedDays = (from, to, changed) => {
    if (from === '' || to === '' || from <= to) {
        return [from, to];
    }
    return changed === 'from' ? [from, from] : [to, to];
};

/**
 * Starts the activity report.
 *
 * @param {string} selector Selector of the element of the list.
 * @returns {Promise<List>}
 */
export const init = async(selector) => {
    // The box of the table takes the height the window leaves it.
    fitTables();
    const root = document.querySelector(selector);
    const config = JSON.parse(root.dataset.config);
    const toolbar = root.querySelector('[data-region="filters"]');
    const search = toolbar.querySelector('input[name="search"]');
    const menu = toolbar.querySelector('[data-menu="date"]');
    const toggle = menu.querySelector('[data-menu-toggle]');
    const panel = menu.querySelector('.dd-select-menu');
    const from = menu.querySelector('input[name="datefrom"]');
    const to = menu.querySelector('input[name="dateto"]');
    const reset = toolbar.querySelector('[data-action="reset-filters"]');
    const [range, since, until] = await getStrings([
        {key: 'filter_date_range', component: 'local_delegateaccount', param: {from: '{from}', to: '{to}'}},
        {key: 'filter_date_since', component: 'local_delegateaccount', param: '{n}'},
        {key: 'filter_date_until', component: 'local_delegateaccount', param: '{n}'},
    ]);
    const [emptytitle, emptytext, nolog] = await Promise.all([
        getString('activity_empty_title', 'local_delegateaccount'),
        getString('activity_empty_text', 'local_delegateaccount'),
        getString('activity_nolog', 'local_delegateaccount'),
    ]);
    let haslog = true;
    const list = new List(root, {
        method: 'local_delegateaccount_get_activity_list',
        template: 'local_delegateaccount/activity/table',
        defaults: {datefrom: '', dateto: '', search: '', page: 0, perpage: 12},
        args: (state) => ({
            delegationid: config.delegationid,
            datefrom: state.datefrom,
            dateto: state.dateto,
            search: state.search,
            page: state.page,
            perpage: state.perpage,
        }),
        isFiltered: (state) => FILTERS.some((name) => state[name] !== ''),
        cleared: Object.fromEntries(FILTERS.map((name) => [name, ''])),
        onClear: () => {
            search.value = '';
        },
        context: (response) => {
            haslog = response.haslog;
            return {rows: response.rows};
        },
        empty: () => ({icon: 'i/log', title: emptytitle, text: haslog ? emptytext : nolog}),
    });
    const open = (show) => {
        panel.hidden = !show;
        toggle.setAttribute('aria-expanded', show ? 'true' : 'false');
    };
    // What the menu says: the period chosen, the two days or one of them, tinted with its cross while it narrows the list.
    const paint = () => {
        const state = list.state;
        const found = Object.entries(periods(menu.dataset.min, menu.dataset.max))
            .find(([, days]) => days[0] === state.datefrom && days[1] === state.dateto);
        const label = toggle.querySelector('[data-region="menu-label"]');
        let text = label.dataset.label;
        if (found) {
            text = menu.querySelector(`[data-preset="${found[0]}"]`).textContent.trim();
        } else if (state.datefrom && state.dateto) {
            text = range.replace('{from}', state.datefrom).replace('{to}', state.dateto);
        } else if (state.datefrom) {
            text = since.replace('{n}', state.datefrom);
        } else if (state.dateto) {
            text = until.replace('{n}', state.dateto);
        }
        const active = Boolean(state.datefrom || state.dateto);
        label.textContent = text;
        toggle.classList.toggle('border-primary', active);
        toggle.classList.toggle('dd-select-set', active);
        menu.querySelector('[data-menu-clear]').hidden = !active;
        from.value = state.datefrom || '';
        to.value = state.dateto || '';
        reset.disabled = !FILTERS.some((name) => (state[name] || '') !== '');
    };
    const change = (changes) => {
        list.update(Object.assign({page: 0}, changes));
        paint();
    };
    search.value = list.state.search || '';
    search.addEventListener('input', debounce(() => change({search: search.value.trim()}), 300));
    search.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') {
            event.preventDefault();
        }
    });
    toggle.addEventListener('click', () => open(panel.hidden));
    menu.addEventListener('click', (event) => {
        const preset = event.target.closest('[data-preset]');
        if (preset) {
            const [first, last] = periods(menu.dataset.min, menu.dataset.max)[preset.dataset.preset];
            open(false);
            change({datefrom: first, dateto: last});
        }
    });
    from.addEventListener('change', () => {
        const [first, last] = orderedDays(from.value, list.state.dateto || '', 'from');
        change({datefrom: first, dateto: last});
    });
    to.addEventListener('change', () => {
        const [first, last] = orderedDays(list.state.datefrom || '', to.value, 'to');
        change({datefrom: first, dateto: last});
    });
    menu.querySelector('[data-menu-clear]').addEventListener('click', () => change({datefrom: '', dateto: ''}));
    reset.addEventListener('click', () => {
        search.value = '';
        change({search: '', datefrom: '', dateto: ''});
    });
    document.addEventListener('pointerdown', (event) => {
        if (!menu.contains(event.target)) {
            open(false);
        }
    });
    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') {
            open(false);
        }
    });
    await list.init();
    paint();
    return list;
};
